/* V0.2: readable type, hotline entry points, configurable Mandarin speech,
   and explicitly local-only anonymous experience sharing. */
const HOTLINES = {
  '12315': {title:'消费者投诉举报', short:'消费投诉举报', summary:'消费纠纷、市场监管领域投诉举报。', source:'https://www.samr.gov.cn/hd/', sourceName:'国家市场监督管理总局'},
  '12348': {title:'公共法律服务热线', short:'法律咨询与援助指引', summary:'法律咨询、法律援助及相关公共法律服务指引。', source:'https://www.moj.gov.cn/pub/sfbgwapp/zwgk/jdhyApp/202105/t20210517_396040.html', sourceName:'司法部'}
};
function hotlineSection(){return `<section class="hotline-section" aria-labelledby="hotline-heading"><div class="section-head"><h2 id="hotline-heading">需要帮助，打个电话</h2><span class="hotline-hint">点击号码了解并拨打</span></div><div class="hotline-grid">${Object.entries(HOTLINES).map(([number,h])=>`<button class="hotline-card" data-hotline="${number}" aria-label="${number} ${h.title}"><span class="hotline-icon">${icon('phone')}</span><span><strong>${number}</strong><span class="hotline-label">${h.short}</span></span>${icon('chevron','arrow')}</button>`).join('')}</div></section>`;}
function hotlineDialog(number){const h=HOTLINES[number];if(!h)return;stopReading();modal(`${number} · ${h.title}`,`<p>${h.summary}</p><p>点击下方按钮打开设备拨号界面，由您确认是否拨出。具体服务时间和受理范围以当地热线为准。</p><a class="primary" href="tel:${number}">${icon('phone')}拨打 ${number}</a><p class="source-link">用途说明：<a href="${h.source}" target="_blank" rel="noopener noreferrer">${h.sourceName} ↗</a></p>`);}
function sharingEntry(){return `<section class="sharing-entry"><span class="icon-box peach">${icon('chat')}</span><div><span class="label">夕阳树洞 · 匿名分享</span><h2>有些经历，说出来就轻松一点</h2><p>记录自己的故事，听见不同的经历。</p><span class="local-badge">本机演示 · 不向他人公开</span></div><button class="primary" data-go="stories">去看看 ${icon('arrow')}</button></section>`;}

// V0.3 removes browser speech. Reviewed recordings are handled in mobile.js.

const STORY_TOPICS=['全部','防骗经历','维权记录','日常心声'];
const STORY_EXAMPLES=[
 {id:'example-call',topic:'防骗经历',title:'接到“熟人”借钱电话，我先找家人聊了聊',body:'【虚构示例】电话里的声音很像熟人，但我心里还是有些不踏实。我没有急着做决定，而是先找家人一起核实。有人陪着商量，心里安稳了许多。',createdAt:null,example:true,comments:[]},
 {id:'example-record',topic:'维权记录',title:'把事情一件件记下来，心里没那么乱了',body:'【虚构示例】一开始，我不知道该从哪里说起。后来试着把时间、经过和手里的材料分别记下来，才发现可以慢慢整理，不用一下子说清楚。',createdAt:null,example:true,comments:[]},
 {id:'example-family',topic:'日常心声',title:'有些不懂的事，问一问也没关系',body:'【虚构示例】以前怕麻烦孩子，手机上不会操作的地方总是自己琢磨。现在试着把问题说出来，一起看看，反而轻松了。希望大家也能多一点耐心。',createdAt:null,example:true,comments:[]}
];
let storyFilter='全部', storyDraft={title:'',body:'',topic:'防骗经历'};
function storyData(){const data=readLocal('yihu-stories-v1',{posts:[],comments:{}});return {posts:Array.isArray(data?.posts)?data.posts.filter(p=>p&&typeof p.id==='string'&&typeof p.title==='string'&&typeof p.body==='string'&&!p.id.startsWith('example-')):[],comments:data?.comments&&typeof data.comments==='object'?data.comments:{}};}
function allStories(){return [...storyData().posts,...STORY_EXAMPLES];}
function storyComments(id){const c=storyData().comments[id];return Array.isArray(c)?c.filter(x=>x&&typeof x.body==='string'):[];}
function saveStories(data){if(!saveLocal('yihu-stories-v1',data)){toast('本机空间不足或存储不可用，未能保存，请保留输入后重试。');return false;}return true;}
function localStoryNotice(){return '<div class="notice soft story-notice">本机演示：帖子和评论只在当前浏览器可见，不会发给其他用户。请勿填写真实姓名、电话、身份证号或转账账号。</div>';}
function storiesPage(){const list=allStories().filter(p=>storyFilter==='全部'||p.topic===storyFilter);return `${back()}${heading('夕阳树洞','慢慢说，总有一些经历值得被听见。')}<div class="story-topline"><span class="local-badge">匿名分享 · 本机演示</span><button class="primary" data-go="story-new">${icon('plus')}分享我的经历</button></div>${localStoryNotice()}<div class="chips" aria-label="经历分类">${STORY_TOPICS.map(t=>`<button class="chip ${storyFilter===t?'active':''}" data-story-filter="${t}" aria-pressed="${storyFilter===t}">${t}</button>`).join('')}</div><div class="story-list">${list.map(p=>`<button class="story-card" data-go="story/${esc(p.id)}"><div class="story-meta"><span class="story-avatar">${icon('user')}</span><span>${p.example?'匿名长辈 · 虚构示例':'匿名的我 · 仅本机'}</span><span class="story-topic">${esc(p.topic)}</span></div><h2>${esc(p.title)}</h2><p>${esc(p.body.slice(0,140))}${p.body.length>140?'…':''}</p><div class="story-footer"><span>${p.example?'用于展示分享样式':stamp(p.createdAt)}</span><span>${icon('chat')}${storyComments(p.id).length} 条本机评论</span></div></button>`).join('')||'<div class="empty"><h2>这里还没有故事</h2><p>可以记录一段自己的经历。</p></div>'}</div>`;}
function storyCompose(){return `${back('stories','返回夕阳树洞')}${heading('分享我的经历','不需要署名，按自己的节奏慢慢说。')}${localStoryNotice()}<form id="story-form" class="form-panel"><label class="field"><span class="field-label">想聊些什么？</span><select name="topic">${STORY_TOPICS.slice(1).map(t=>`<option ${storyDraft.topic===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span class="field-label">给经历起个标题 <span class="optional">最多 40 字</span></span><input name="title" maxlength="40" required minlength="2" value="${esc(storyDraft.title)}" placeholder="例如：今天，我和家人一起核实了一通电话"></label><label class="field"><span class="field-label">说说发生了什么 <span class="optional">最多 2000 字</span></span><textarea name="body" maxlength="2000" minlength="5" required placeholder="说说您的经历和感受。不要填写他人的真实身份或联系方式。">${esc(storyDraft.body)}</textarea></label><p class="field-hint">保存后显示为“匿名的我”，只在这台设备的当前浏览器可见。</p><p class="error" id="story-error" role="alert"></p><div class="actions"><button type="button" class="secondary" data-go="stories">暂不分享</button><button type="submit" class="primary">匿名保存到本机 ${icon('check')}</button></div></form>`;}
function storyDetail(id){const p=allStories().find(x=>x.id===id);if(!p)return `${back('stories','返回夕阳树洞')}${heading('这篇分享不在当前浏览器中')}`;const comments=storyComments(id);return `${back('stories','返回夕阳树洞')}<article class="article-body story-detail"><div class="story-meta"><span class="story-avatar">${icon('user')}</span><span>${p.example?'匿名长辈 · 虚构示例':'匿名的我 · 仅本机'}</span></div><span class="label">${esc(p.topic)}</span><h1>${esc(p.title)}</h1><p class="story-text">${esc(p.body)}</p>${p.example?'<div class="notice">这是虚构情景，用来演示匿名分享样式，不是真实用户发帖。</div>':`<button class="text-btn danger" data-story-delete="${esc(id)}">删除我的分享</button>`}</article><div class="section-head"><h2>聊一聊 <span class="optional">${comments.length} 条本机评论</span></h2></div><div class="comment-list">${comments.map(c=>`<article class="comment"><div class="story-meta"><span>匿名的我 · 仅本机</span><button class="text-btn danger" data-comment-delete="${esc(c.id)}" data-story="${esc(id)}" aria-label="删除这条评论">删除</button></div><p>${esc(c.body)}</p><small>${stamp(c.createdAt)}</small></article>`).join('')||'<p class="subtext">还没有本机评论，可以说一句暖心的话。</p>'}</div><form id="comment-form" data-story="${esc(id)}" class="form-panel comment-form"><label class="field"><span class="field-label">我的留言 <span class="optional">最多 500 字</span></span><textarea name="comment" maxlength="500" required placeholder="分享感受，友善交流，不留下个人信息。"></textarea></label><p class="error" id="comment-error" role="alert"></p><button class="primary" type="submit">匿名留言到本机</button></form>${localStoryNotice()}`;}
function privateInfo(text){return /(?<!\d)1[3-9]\d{9}(?!\d)|(?<!\d)\d{17}[\dXx](?!\d)|(?<!\d)\d{16,19}(?!\d)|[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/.test(text);}
function newLocalId(){return globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);}
function handleStorySubmit(e){if(e.target.id==='story-form'){const d=new FormData(e.target),title=String(d.get('title')).trim(),body=String(d.get('body')).trim(),topic=String(d.get('topic'));if(title.length<2||body.length<5){$('#story-error').textContent='请写至少 2 个字的标题和 5 个字的经历。';return;}if(privateInfo(title+' '+body)){$('#story-error').textContent='内容中可能有电话、证件、账号或邮箱，请隐去后再保存。';return;}const data=storyData();if(data.posts.length>=100){$('#story-error').textContent='本机已保存 100 篇分享，请先删除不需要的内容。';return;}const id=newLocalId();data.posts.unshift({id,title,body,topic:STORY_TOPICS.includes(topic)?topic:'日常心声',createdAt:new Date().toISOString()});if(saveStories(data)){storyDraft={title:'',body:'',topic:'防骗经历'};navigate('story/'+id);toast('匿名分享已保存到本机，未向其他用户发布');}}else if(e.target.id==='comment-form'){const id=e.target.dataset.story,body=String(new FormData(e.target).get('comment')).trim();if(!body){$('#comment-error').textContent='请先写一点想说的话。';return;}if(privateInfo(body)){$('#comment-error').textContent='请先隐去电话、证件、账号或邮箱。';return;}const data=storyData(),comments=storyComments(id);if(comments.length>=100){$('#comment-error').textContent='此帖本机评论已达 100 条，请先删除不需要的评论。';return;}data.comments[id]=[...comments,{id:newLocalId(),body,createdAt:new Date().toISOString()}];if(saveStories(data)){render();toast('留言已保存到本机');}}}
document.addEventListener('submit',e=>{if(['story-form','comment-form'].includes(e.target.id)){e.preventDefault();handleStorySubmit(e);}});
document.addEventListener('input',e=>{if(e.target.closest('#story-form'))storyDraft[e.target.name]=e.target.value;});
document.addEventListener('change',e=>{if(e.target.closest('#story-form'))storyDraft[e.target.name]=e.target.value;});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.hotline){hotlineDialog(b.dataset.hotline);return;}if(b.dataset.storyFilter){storyFilter=b.dataset.storyFilter;render();return;}if(b.dataset.storyDelete){modal('删除这篇本机分享？','<p>此操作会同时删除这篇分享下的本机评论，无法撤销。</p><button class="primary" data-story-remove="'+esc(b.dataset.storyDelete)+'">确认删除分享</button><button class="secondary" data-action="close">保留分享</button>');return;}if(b.dataset.storyRemove){const data=storyData();data.posts=data.posts.filter(p=>p.id!==b.dataset.storyRemove);delete data.comments[b.dataset.storyRemove];if(saveStories(data)){closeModal();navigate('stories');toast('已删除本机分享');}return;}if(b.dataset.commentDelete){modal('删除这条本机评论？',`<p>删除后无法恢复。</p><button class="primary" data-comment-remove="${esc(b.dataset.commentDelete)}" data-story="${esc(b.dataset.story)}">确认删除评论</button><button class="secondary" data-action="close">保留评论</button>`);return;}if(b.dataset.commentRemove){const data=storyData();data.comments[b.dataset.story]=storyComments(b.dataset.story).filter(c=>c.id!==b.dataset.commentRemove);if(saveStories(data)){closeModal();render();toast('已删除本机评论');}return;}});
